 static object BufferSnapshot(EnvDTE.DTE d,string file){if(d.ActiveDocument==null||!string.Equals(d.ActiveDocument.FullName,file,StringComparison.OrdinalIgnoreCase))throw new Exception("Active document changed; refusing snapshot");var doc=(EnvDTE.TextDocument)d.ActiveDocument.Object("TextDocument");var s=(EnvDTE.TextSelection)d.ActiveDocument.Selection;var begin=doc.StartPoint.CreateEditPoint();return new {zoom=ReadZoom(d),text=begin.GetText(doc.EndPoint),caret=begin.GetText(s.ActivePoint).Length,selectionStart=begin.GetText(s.TopPoint).Length,selectionLength=s.Text.Length,selectedText=s.Text};}
 static bool SameSnapshot(object actual,Dictionary<string,object> expected,string[] fields=null){if(actual==null||expected==null)return false;var core=new[]{"text","caret","selectionStart","selectionLength","selectedText"};if(fields!=null&&(!core.All(fields.Contains)||fields.Any(k=>!core.Contains(k)&&k!="zoom")))return false;var a=(Dictionary<string,object>)json.DeserializeObject(json.Serialize(actual));foreach(var key in fields??new[]{"text","caret","selectionStart","selectionLength","selectedText"})if(!a.ContainsKey(key)||!expected.ContainsKey(key)||Convert.ToString(a[key])!=Convert.ToString(expected[key]))return false;return true;}
 static void FocusEditor(EnvDTE.DTE d,int pid,string file){AssertNoBlockingDialog(d);if(d.ActiveDocument==null||d.ActiveDocument.FullName!=file)throw new Exception("Wrong fixture before focus");Foreground((IntPtr)d.MainWindow.HWnd);var root=AutomationElement.FromHandle((IntPtr)d.MainWindow.HWnd);var editor=root.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.AutomationIdProperty,"WpfTextView"));if(editor==null||!editor.Current.IsEnabled||editor.Current.IsOffscreen)throw new Exception("No visible enabled editor");var selection=(EnvDTE.TextSelection)d.ActiveDocument.Selection;int top=selection.TopPoint.AbsoluteCharOffset,bottom=selection.BottomPoint.AbsoluteCharOffset;try{editor.SetFocus();}catch(InvalidOperationException){var rect=editor.Current.BoundingRectangle;if(rect.Width<10||rect.Height<10)throw;uint foreground;GetWindowThreadProcessId(GetForegroundWindow(),out foreground);if(foreground!=pid)throw new Exception("Wrong foreground before editor focus click");SetCursorPos((int)(rect.Left+rect.Width/2),(int)(rect.Top+rect.Height/2));mouse_event(2,0,0,UIntPtr.Zero);mouse_event(4,0,0,UIntPtr.Zero);Pump(100);selection.MoveToAbsoluteOffset(top,false);selection.MoveToAbsoluteOffset(bottom,true);}Pump(150);if(!editor.Current.HasKeyboardFocus)throw new Exception("Editor does not have keyboard focus");}
 static void AssertNoBlockingDialog(EnvDTE.DTE d){var root=AutomationElement.FromHandle((IntPtr)d.MainWindow.HWnd);foreach(AutomationElement w in root.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Window))){object pattern;bool modal=w.TryGetCurrentPattern(WindowPattern.Pattern,out pattern)&&((WindowPattern)pattern).Current.IsModal;if(modal||w.Current.Name.Contains("검색 데이터베이스와 IntelliSense"))throw new Exception("Environment blocked by dialog: "+w.Current.Name+"; no keyboard test sent");}}
 static int RunBehavior(EnvDTE.DTE d,int pid,string root,string planFile){var output=Path.Combine(root,"behavior.json");var rows=new List<object>();var events=d.Events;var commandEvents=events.CommandEvents;commandEvents.BeforeExecute+=Before;try{var plan=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(planFile));ValidateOracles(plan);var relevant=new[]{274,269};foreach(var id in relevant)SaveBinding(d.Commands.Item("{f9d77864-fac8-457e-bd4f-552715151b6c}",id));SaveBinding(d.Commands.Item("Edit.MoveSelectedLinesDown",0));foreach(var id in relevant){var c=d.Commands.Item("{f9d77864-fac8-457e-bd4f-552715151b6c}",id);var old=(object[])c.Bindings;c.Bindings=old.Select(x=>(object)EnglishBinding(x.ToString())).Concat(old.Select(x=>(object)("텍스트 편집기::"+EnglishBinding(x.ToString()).Split(new[]{"::"},StringSplitOptions.None).Last()))).Distinct().ToArray();}File.WriteAllText(Path.Combine(root,"behavior-bindings-before.json"),json.Serialize(saved.Select(x=>new{name=x.Item1.Name,guid=x.Item1.Guid,id=x.Item1.ID,bindings=x.Item2})));
 foreach(Dictionary<string,object> c in (object[])plan["cases"]){string id=(string)c["id"];string file=Path.Combine(root,id+"-"+Guid.NewGuid().ToString("N")+".cpp");var fields=c.ContainsKey("compareFields")?((object[])c["compareFields"]).Select(x=>x.ToString()).ToArray():new[]{"text","caret","selectionStart","selectionLength","selectedText"};string error=null;object before=null,after=null,undo=null;object actionCommands=null,undoCommands=null;bool match=false,undoMatch=false,input=false;try{File.WriteAllText(file,(string)c["text"]);var w=d.ItemOperations.OpenFile(file);w.Activate();Pump(200);double setupZoom=c.ContainsKey("preZoom")?Convert.ToDouble(c["preZoom"]):100;if(ReadZoom(d)!=setupZoom)SetZoom(d,pid,setupZoom);var s=(EnvDTE.TextSelection)d.ActiveDocument.Selection;s.StartOfDocument(false);int start=Convert.ToInt32(c["start"]),length=Convert.ToInt32(c["length"]);int beforeMoves=((string)c["text"]).Substring(0,start).Replace("\r\n","\n").Length;int selectedMoves=((string)c["text"]).Substring(start,length).Replace("\r\n","\n").Length;if(beforeMoves>0)s.CharRight(false,beforeMoves);if(selectedMoves>0)s.CharRight(true,selectedMoves);FocusEditor(d,pid,file);before=BufferSnapshot(d,file);CapturePhase(d,root,id,"before");var expectedBefore=new Dictionary<string,object>{{"text",c["text"]},{"caret",start+length},{"selectionStart",start},{"selectionLength",length},{"selectedText",((string)c["text"]).Substring(start,length)}};if(c.ContainsKey("preZoom"))expectedBefore["zoom"]=c["preZoom"];if(!SameSnapshot(before,expectedBefore,fields))throw new Exception("Fixture/selection setup does not match plan");observed.Clear();signatures.Clear();foreach(string chord in (object[])c["keys"]){Keys(pid,chord.Split('+').Select(Key).ToArray());Pump(450);}input=true;actionCommands=observed.ToArray();after=BufferSnapshot(d,file);CapturePhase(d,root,id,"after");match=SameSnapshot(after,(Dictionary<string,object>)c["expected"],fields);if(Convert.ToBoolean(c["verifyUndo"])){FocusEditor(d,pid,file);observed.Clear();Keys(pid,new ushort[]{17,90});Pump(600);undoCommands=observed.ToArray();undo=BufferSnapshot(d,file);CapturePhase(d,root,id,"undo");undoMatch=SameSnapshot(undo,c["expectedUndo"] as Dictionary<string,object>);}var bounds=System.Windows.Forms.Screen.FromHandle((IntPtr)d.MainWindow.HWnd).Bounds;using(var bmp=new System.Drawing.Bitmap(bounds.Width,bounds.Height)){using(var g=System.Drawing.Graphics.FromImage(bmp))g.CopyFromScreen(bounds.Location,System.Drawing.Point.Empty,bounds.Size);bmp.Save(Path.Combine(root,id+".png"),System.Drawing.Imaging.ImageFormat.Png);}d.ActiveDocument.Close(EnvDTE.vsSaveChanges.vsSaveChangesNo);}catch(Exception ex){error=ex.Message;}bool requiredUndo=Convert.ToBoolean(c["verifyUndo"]);rows.Add(new{id,physicalInput=input,expected=c["expected"],before,after,undo,actionCommands,undoCommands,bufferCursorSelectionMatch=match,undoRequired=requiredUndo,undoMatchesVA=undoMatch,passed=error==null&&input&&match&&(!requiredUndo||undoMatch),error,oracleFile=c["oracleFile"]});File.WriteAllText(output,json.Serialize(new{pid,cases=rows,scope="Physical OS keys, exact buffer/caret/selection and requested Undo vs archived actual VA output"}));Console.WriteLine(id+" output="+match+" undo="+undoMatch+" "+error);}
 }catch(Exception ex){Console.WriteLine(ex);File.WriteAllText(Path.Combine(root,"fatal.txt"),ex.ToString());return 1;}finally{commandEvents.BeforeExecute-=Before;GC.KeepAlive(events);RestoreBindings();File.WriteAllText(Path.Combine(root,"behavior-bindings-restored.json"),json.Serialize(saved.Select(x=>new{name=x.Item1.Name,matched=((object[])x.Item1.Bindings).Select(v=>EnglishBinding(v.ToString())).SequenceEqual(x.Item2.Select(v=>EnglishBinding(v.ToString())))})));}return 0;}

 static void CapturePhase(EnvDTE.DTE d,string root,string id,string phase){var b=System.Windows.Forms.Screen.FromHandle((IntPtr)d.MainWindow.HWnd).Bounds;using(var bitmap=new System.Drawing.Bitmap(b.Width,b.Height)){using(var g=System.Drawing.Graphics.FromImage(bitmap))g.CopyFromScreen(b.Location,System.Drawing.Point.Empty,b.Size);bitmap.Save(Path.Combine(root,id+"-"+phase+".png"),System.Drawing.Imaging.ImageFormat.Png);}}
 static void ValidateOracles(Dictionary<string,object> plan){foreach(Dictionary<string,object> c in (object[])plan["cases"]){string file=(string)c["oracleFile"],hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();if(hash!=(string)c["oracleSha256"])throw new Exception("Stale or changed VA evidence");var evidence=(Dictionary<string,object>)json.DeserializeObject(File.ReadAllText(file));var actual=((object[])evidence["cases"]).Cast<Dictionary<string,object>>().Single(x=>(string)x["id"]==(string)c["id"]);if(actual.ContainsKey("error")&&actual["error"]!=null)throw new Exception("Oracle is an error");if(!SameSnapshot(c["expected"],(Dictionary<string,object>)actual["after"],c.ContainsKey("compareFields")?((object[])c["compareFields"]).Select(x=>x.ToString()).ToArray():null))throw new Exception("Expected output is not the actual VA output");}}
 static int ComparatorSelfTest(){var x=new Dictionary<string,object>{{"text","()"},{"caret",1},{"selectionStart",1},{"selectionLength",0},{"selectedText",""}};int passed=0;if(SameSnapshot(x,x))passed++;foreach(var key in new[]{"text","caret","selectionStart","selectionLength","selectedText"}){var changed=new Dictionary<string,object>(x);changed[key]=key=="text"||key=="selectedText"?(object)"wrong":99;if(!SameSnapshot(changed,x))passed++;}if(!SameSnapshot(null,x))passed++;if(!SameSnapshot(new Dictionary<string,object>(),x))passed++;if(!SameSnapshot(x,x,new string[0]))passed++;if(!SameSnapshot(x,x,new[]{"text"}))passed++;var z=new Dictionary<string,object>(x);z["zoom"]=140;var expectedZoom=new Dictionary<string,object>(x);expectedZoom["zoom"]=100;if(!SameSnapshot(z,expectedZoom,coreFieldsForZoom()))passed++;Console.WriteLine("Comparator adversarial self-tests "+passed+"/11");return passed==11?0:1;}
static string[] coreFieldsForZoom(){return new[]{"text","caret","selectionStart","selectionLength","selectedText","zoom"};}
 static AutomationElement ZoomControl(EnvDTE.DTE d){return AutomationElement.FromHandle((IntPtr)d.MainWindow.HWnd).FindFirst(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Edit),new OrCondition(new PropertyCondition(AutomationElement.NameProperty,"확대/축소 값"),new PropertyCondition(AutomationElement.NameProperty,"Zoom level"))));}
 static double? ReadZoom(EnvDTE.DTE d){var z=ZoomControl(d);if(z==null)return null;object pattern;double value;if(!z.TryGetCurrentPattern(ValuePattern.Pattern,out pattern))return null;return double.TryParse(((ValuePattern)pattern).Current.Value.Replace("%","").Trim(),System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out value)?(double?)value:null;}
 static void SetZoom(EnvDTE.DTE d,int pid,double value){AssertNoBlockingDialog(d);var z=ZoomControl(d);if(z==null)throw new Exception("No zoom control");Foreground((IntPtr)d.MainWindow.HWnd);z.SetFocus();((ValuePattern)z.GetCurrentPattern(ValuePattern.Pattern)).SetValue(value.ToString(System.Globalization.CultureInfo.InvariantCulture)+"%");Keys(pid,new ushort[]{13});Pump(250);if(ReadZoom(d)!=value)throw new Exception("Zoom setup failed");}
